window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d967439aeccf8ef3"]={"versions": [{"id": "FIG-d967439aeccf8ef3", "releases": ["R1.3.0", "R17-03_R1.1.0", "R17-10_R1.2.0", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein Bit-Feld- und Protokollformat-Diagramm (Wire-Format-Spezifikation) für das AUTOSAR SOME/IP Service Discovery Protocol (<code>AUTOSAR_PRS_SOMEIPServiceDiscoveryProtocol</code>). Es definiert das binäre Speicher- und Übertragungslayout eines SOME/IP-SD Eventgroup Entries über einer 32-Bit-Rasterbreite (Bit-Offsets 0 bis 31) mit einer Gesamtlänge von 16 Bytes (128 Bits). Der Eintrag wird innerhalb von SOME/IP-SD-Nachrichten transportiert, um Publish/Subscribe-Interaktionen für Eventgruppen zwischen Server- und Client-Instanzen über das Netzwerk zu steuern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format umfasst vier aufeinanderfolgende 32-Bit-Zeilen:</p>\n<ul class=\"fig-list\">\n<li><strong>Zeile 1 (Header/Optionen)</strong>:</li>\n<li><code>Type</code> (Bit 0–7, 8 Bit): Kennzeichnung des Entry-Typs (z. B. Find/Offer bzw. Subscribe/StopSubscribe).</li>\n<li><code>Index 1st options</code> (Bit 8–15, 8 Bit): Startindex im Option-Array für den ersten Optionslauf.</li>\n<li><code>Index 2nd options</code> (Bit 16–23, 8 Bit): Startindex im Option-Array für den zweiten Optionslauf.</li>\n<li><code># of opt 1</code> (Bit 24–27, 4 Bit): Anzahl der Optionen im ersten Optionslauf.</li>\n<li><code># of opt 2</code> (Bit 28–31, 4 Bit): Anzahl der Optionen im zweiten Optionslauf.</li>\n<li><strong>Zeile 2 (Adressierung)</strong>:</li>\n<li><code>Service ID</code> (Bit 0–15, 16 Bit): Eindeutige Kennung des SOME/IP-Dienstes.</li>\n<li><code>Instance ID</code> (Bit 16–31, 16 Bit): Instanzkennung des angebotenen bzw. angefragten Dienstes.</li>\n<li><strong>Zeile 3 (Version & Lebensdauer)</strong>:</li>\n<li><code>Major Version</code> (Bit 0–7, 8 Bit): Hauptversionsnummer des Service-Interfaces.</li>\n<li><code>TTL</code> (Bit 8–31, 24 Bit): Time to Live in Sekunden für die Gültigkeit des Eintrags.</li>\n<li><strong>Zeile 4 (Eventgruppen-Spezifikation)</strong>:</li>\n<li><code>Reserved</code> (Bit 0–7, 8 Bit): Reserviertes Feld.</li>\n<li><code>Initial Data Requested Flag</code> (Bit 8, 1 Bit): Flag zur Anforderung von Initialwerten nach dem Abonnement.</li>\n<li><code>Reserved2</code> (Bit 9–11, 3 Bit): Zweites reserviertes Feld.</li>\n<li><code>Counter</code> (Bit 12–15, 4 Bit): Zähler zur Differenzierung und Reihenfolgeüberwachung von Subscriptions.</li>\n<li><code>Eventgroup ID</code> (Bit 16–31, 16 Bit): Eindeutige Kennung der adressierten Eventgruppe.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Eventgroup Entry dient der ereignisbasierten Kommunikation (Publish/Subscribe) im SOME/IP-SD:</p>\n<ul class=\"fig-list\">\n<li>Ein Client sendet einen Subscribe-Eventgroup-Entry an den Server; der Server beantwortet dies mit einem Subscribe-Eventgroup-Ack oder Nack.</li>\n<li>Das <code>Initial Data Requested Flag</code> signalisiert dem Server bei einer Subscription, ob unverzüglich nach Bestätigung des Abonnements der aktuelle Datenstand der Eventgruppe an den Client übertragen werden soll.</li>\n<li>Der <code>Counter</code> wird inkrementiert, um wiederholte oder parallele Anfragen zu korrelieren und Replay-Effekte zu erkennen.</li>\n<li><code>TTL</code> bestimmt den Timeout-Zeitraum; vor Ablauf muss der Client den Eintrag per neuer Subscription erneuern, oder er beendet das Abonnement mit einem TTL-Wert von 0 (StopSubscribe).</li>\n<li>Die Optionsläufe (<code>Index 1st options</code>, <code>Index 2nd options</code>, <code># of opt 1</code>, <code># of opt 2</code>) referenzieren Netzwerkendpunkte (IPv4/IPv6 Unicast- und Multicast-Endpoints) im Optionsblock der SD-Nachricht.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Layout ist normativ für die Serialisierung und Deserialisierung von SOME/IP-SD Eventgroup Entries in AUTOSAR Classic und Adaptive Plattformen:</p>\n<ul class=\"fig-list\">\n<li>Alle Multi-Byte-Felder (<code>Service ID</code>, <code>Instance ID</code>, <code>TTL</code>, <code>Eventgroup ID</code>) unterliegen der Big-Endian-Bytereihenfolge (Network Byte Order).</li>\n<li>Für <code>Reserved</code> (8 Bit) und <code>Reserved2</code> (3 Bit) ist beim Senden der spezifizierte Standardwert (in der Regel <code>0x00</code> bzw. alle Bits 0) zu setzen und beim Empfang zu ignorieren.</li>\n<li>Bit-Extraktionen in Zeile 4 erfordern bitgenaue Maskierung: Bit 8 für das Flag, Bits 9–11 für <code>Reserved2</code> und Bits 12–15 für den 4-Bit-<code>Counter</code>.</li>\n<li>Ein Wert von <code>0</code> in <code># of opt 1</code> bzw. <code># of opt 2</code> definiert einen leeren Optionslauf, bei dem der zugehörige Index ignoriert wird.</li>\n</ul>"}, {"id": "FIG-f4e562ab60acb374", "releases": ["R1.5.1", "R19-03", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein Bit-Feld- und Protokollformat-Diagramm (Wire-Format-Spezifikation) für das AUTOSAR SOME/IP Service Discovery Protocol (<code>AUTOSAR_PRS_SOMEIPServiceDiscoveryProtocol</code>). Es definiert das binäre Speicher- und Übertragungslayout eines SOME/IP-SD Eventgroup Entries über einer 32-Bit-Rasterbreite (Bit-Offsets 0 bis 31) mit einer Gesamtlänge von 16 Bytes (128 Bits). Der Eintrag wird innerhalb von SOME/IP-SD-Nachrichten transportiert, um Publish/Subscribe-Interaktionen für Eventgruppen zwischen Server- und Client-Instanzen über das Netzwerk zu steuern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format umfasst vier aufeinanderfolgende 32-Bit-Zeilen:</p>\n<ul class=\"fig-list\">\n<li><strong>Zeile 1 (Header/Optionen)</strong>:</li>\n<li><code>Type</code> (Bit 0–7, 8 Bit): Kennzeichnung des Entry-Typs (z. B. Find/Offer bzw. Subscribe/StopSubscribe).</li>\n<li><code>Index 1st options</code> (Bit 8–15, 8 Bit): Startindex im Option-Array für den ersten Optionslauf.</li>\n<li><code>Index 2nd options</code> (Bit 16–23, 8 Bit): Startindex im Option-Array für den zweiten Optionslauf.</li>\n<li><code># of opt 1</code> (Bit 24–27, 4 Bit): Anzahl der Optionen im ersten Optionslauf.</li>\n<li><code># of opt 2</code> (Bit 28–31, 4 Bit): Anzahl der Optionen im zweiten Optionslauf.</li>\n<li><strong>Zeile 2 (Adressierung)</strong>:</li>\n<li><code>Service ID</code> (Bit 0–15, 16 Bit): Eindeutige Kennung des SOME/IP-Dienstes.</li>\n<li><code>Instance ID</code> (Bit 16–31, 16 Bit): Instanzkennung des angebotenen bzw. angefragten Dienstes.</li>\n<li><strong>Zeile 3 (Version & Lebensdauer)</strong>:</li>\n<li><code>Major Version</code> (Bit 0–7, 8 Bit): Hauptversionsnummer des Service-Interfaces.</li>\n<li><code>TTL</code> (Bit 8–31, 24 Bit): Time to Live in Sekunden für die Gültigkeit des Eintrags.</li>\n<li><strong>Zeile 4 (Eventgruppen-Spezifikation)</strong>:</li>\n<li><code>Reserved</code> (Bit 0–7, 8 Bit): Reserviertes Feld.</li>\n<li><code>Initial Data Requested Flag</code> (Bit 8, 1 Bit): Flag zur Anforderung von Initialwerten nach dem Abonnement.</li>\n<li><code>Reserved2</code> (Bit 9–11, 3 Bit): Zweites reserviertes Feld.</li>\n<li><code>Counter</code> (Bit 12–15, 4 Bit): Zähler zur Differenzierung und Reihenfolgeüberwachung von Subscriptions.</li>\n<li><code>Eventgroup ID</code> (Bit 16–31, 16 Bit): Eindeutige Kennung der adressierten Eventgruppe.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Eventgroup Entry dient der ereignisbasierten Kommunikation (Publish/Subscribe) im SOME/IP-SD:</p>\n<ul class=\"fig-list\">\n<li>Ein Client sendet einen Subscribe-Eventgroup-Entry an den Server; der Server beantwortet dies mit einem Subscribe-Eventgroup-Ack oder Nack.</li>\n<li>Das <code>Initial Data Requested Flag</code> signalisiert dem Server bei einer Subscription, ob unverzüglich nach Bestätigung des Abonnements der aktuelle Datenstand der Eventgruppe an den Client übertragen werden soll.</li>\n<li>Der <code>Counter</code> wird inkrementiert, um wiederholte oder parallele Anfragen zu korrelieren und Replay-Effekte zu erkennen.</li>\n<li><code>TTL</code> bestimmt den Timeout-Zeitraum; vor Ablauf muss der Client den Eintrag per neuer Subscription erneuern, oder er beendet das Abonnement mit einem TTL-Wert von 0 (StopSubscribe).</li>\n<li>Die Optionsläufe (<code>Index 1st options</code>, <code>Index 2nd options</code>, <code># of opt 1</code>, <code># of opt 2</code>) referenzieren Netzwerkendpunkte (IPv4/IPv6 Unicast- und Multicast-Endpoints) im Optionsblock der SD-Nachricht.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Layout ist normativ für die Serialisierung und Deserialisierung von SOME/IP-SD Eventgroup Entries in AUTOSAR Classic und Adaptive Plattformen:</p>\n<ul class=\"fig-list\">\n<li>Alle Multi-Byte-Felder (<code>Service ID</code>, <code>Instance ID</code>, <code>TTL</code>, <code>Eventgroup ID</code>) unterliegen der Big-Endian-Bytereihenfolge (Network Byte Order).</li>\n<li>Für <code>Reserved</code> (8 Bit) und <code>Reserved2</code> (3 Bit) ist beim Senden der spezifizierte Standardwert (in der Regel <code>0x00</code> bzw. alle Bits 0) zu setzen und beim Empfang zu ignorieren.</li>\n<li>Bit-Extraktionen in Zeile 4 erfordern bitgenaue Maskierung: Bit 8 für das Flag, Bits 9–11 für <code>Reserved2</code> und Bits 12–15 für den 4-Bit-<code>Counter</code>.</li>\n<li>Ein Wert von <code>0</code> in <code># of opt 1</code> bzw. <code># of opt 2</code> definiert einen leeren Optionslauf, bei dem der zugehörige Index ignoriert wird.</li>\n</ul>"}], "trans": [{"from": "FIG-d967439aeccf8ef3", "to": "FIG-f4e562ab60acb374", "fr": "R1.3.0", "tr": "R1.5.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Textzeile oberhalb des Tabellenheaders (<code>SOME/IP-SD Eventgroup Entry Type is shown in Figure 4.5 ⌋(RS_SOMEIPSD_00006)</code>): Wurde entfernt (Bereinigung von Spezifikationstext-Artefakten im Bild-Header).</li>\n</ul>"}, {"from": "FIG-f4e562ab60acb374", "to": "FIG-d967439aeccf8ef3", "fr": "R1.5.1", "tr": "R17-03_R1.1.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Textzeile oberhalb des Tabellenheaders (<code>SOME/IP-SD Eventgroup Entry Type is shown in Figure 4.5 ⌋(RS_SOMEIPSD_00006)</code>): Wurde wieder eingefügt bzw. ist oberhalb des Headers sichtbar.</li>\n</ul>"}]};
